def save_cns_figure(fig, filename):
    """Standard Academic Figure Skill export: vector PDF + 300dpi PNG preview."""
    fig.savefig(f"{filename}.pdf", bbox_inches="tight", dpi=300)
    fig.savefig(f"{filename}.png", bbox_inches="tight", dpi=300)

from pathlib import Path
import csv, hashlib, json, shutil
import numpy as np
from PIL import Image
import matplotlib.pyplot as plt
from matplotlib.lines import Line2D

V2=Path(__file__).resolve().parent
ROOT=V2.parent
CASE=ROOT.parent
PAPER=Path(r'E:\Project\FlexPPI\paper\revision_v14_20261010')
BLUE='#236AB6'; WARM='#BE7D35'; MD='#62676B'; LIGHT='#D2D5D8'
W,H=183,80
OUTPUT=V2/'figure4e_g_6A77_preview_v2'

def sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()

def rect(x,y,w,h):
    return [x/W,1-(y+h)/H,w/W,h/H]

rows=list(csv.DictReader((CASE/'6A77_all_positions_predictions_and_MD.csv').open(encoding='utf-8-sig')))
h3=sorted([r for r in rows if r['variant']=='full' and r['chain']=='C' and 95<=int(r['author'])<=109],key=lambda r:int(r['author']))
assert len(h3)==15 and [int(r['author']) for r in h3]==list(range(95,110))
x=np.array([int(r['author']) for r in h3])
profiles={}
source=[]
for metric in ['rmsf','chi_entropy']:
    valid=np.array([r[metric+'_valid']=='True' for r in h3])
    pred=np.array([float(r[metric+'_pred']) if v else np.nan for r,v in zip(h3,valid)])
    ref=np.array([float(r[metric+'_MD']) if v else np.nan for r,v in zip(h3,valid)])
    assert np.all(np.isfinite(pred[valid])) and np.all(np.isfinite(ref[valid]))
    profiles[metric]=(pred,ref,valid)
    for r,p,m,v in zip(h3,pred,ref,valid):
        source.append({'panel':'f','chain':'C','author':int(r['author']),'aa':r['aa'],'metric':metric,'valid':bool(v),'Full':float(p) if v else '', 'MD':float(m) if v else ''})
assert profiles['rmsf'][2].sum()==15 and profiles['chi_entropy'][2].sum()==12
contact_rows=list(csv.DictReader((CASE/'hcd3_functional_analysis_20261029/md_audit/all_h3_sidechain_backbone_and_blocks.csv').open(encoding='utf-8-sig')))
r101=next(r for r in contact_rows if r['author']=='101' and r['block']=='all')
occup=np.array([float(r101['backbone_B_fraction_4A']),float(r101['sidechain_B_fraction_4A'])])*100
assert np.allclose(occup,[90.3,2.3])
for group,value in zip(['backbone','sidechain'],occup):
    source.append({'panel':'g','chain':'C','author':101,'aa':'R','metric':group+'_light_chain_contact_percent','valid':True,'Full':'','MD':float(value)})
with (V2/'figure4_extension_source_data.csv').open('w',encoding='utf-8-sig',newline='') as f:
    writer=csv.DictWriter(f,fieldnames=list(source[0]));writer.writeheader();writer.writerows(source)

def heading(fig,label,title,x):
    fig.text(x/W,1-3.5/H,label,fontsize=10,fontweight='bold',va='top',ha='left')
    fig.text((x+6)/W,1-3.5/H,title,fontsize=9,va='top',ha='left')

def molecular_panel(fig):
    meta=json.loads((V2/'final_projection.json').read_text(encoding='utf-8'))
    details=[]
    configs=[('R96',14,(200,30,1510,875),'Internal packing'),('R101',47,(480,80,1400,700),'Light-chain interface')]
    for name,y,crop,title in configs:
        rec=meta[name]
        im=Image.open(V2/rec['png']).convert('RGBA').crop(crop)
        ax=fig.add_axes(rect(2,y,65,26))
        ax.imshow(im);ax.axis('off')
        width,height=im.size
        ax.set_xlim(0,width);ax.set_ylim(height,0)
        def p(key):
            xx,yy=rec['anchors_pixels'][key]
            return (xx-crop[0],yy-crop[1])
        def text_at(text,xy,color=BLACK,ha='left',weight='normal'):
            ax.text(xy[0],xy[1],text,fontsize=7,color=color,ha=ha,va='center',fontweight=weight)
        def short_label(text,anchor,delta,color):
            xy=p(anchor);dest=(xy[0]+delta[0],xy[1]+delta[1])
            ax.annotate(text,xy=xy,xytext=dest,fontsize=7,color=color,va='center',ha='left',
                        arrowprops=dict(arrowstyle='-',color=color,lw=.5,shrinkA=2,shrinkB=4))
        if name=='R96':
            short_label('H:R96','CZ',(85,105),WARM)
            short_label('H:D108','contact_b',(-35,-175),MD)
            mid=(np.array(p('contact_a'))+p('contact_b'))/2
            text_at('2.65 Å',mid+np.array([65,-5]),MD)
        else:
            short_label('H:R101','CZ',(-40,90),WARM)
            short_label('L:Y49','contact_b',(-240,-135),MD)
            mid=(np.array(p('contact_a'))+p('contact_b'))/2
            text_at('3.21 Å',mid+np.array([180,-60]),MD)
        fig.text(6/W,1-(y-1)/H,title,fontsize=7.5,color=MD,va='bottom')
        details.append(dict(name=name,image=str(V2/rec['png']),sha256=sha(V2/rec['png']),crop=list(crop),distance_A=rec['distance'],projection_error_pixels=rec['projection_error_pixels']))
    fig.text(6/W,1-77/H,'6A77 · B5209B Fab',fontsize=7,color=MD)
    return {'views':details,'coordinates':'Same canonical input; independent rigid views and display crops only; no coordinate modifications beyond camera transforms.'}

def profile_panel(fig):
    axes=[]
    for metric,y,ylims,yticks,ylabel in [('rmsf',17,(0,1.28),[0,.5,1.0],'RMSF (Å)'),('chi_entropy',47,(0,4.0),[0,2,4],'Hχ (nats)')]:
        ax=fig.add_axes(rect(81,y,60,22))
        pred,ref,valid=profiles[metric]
        ax.plot(x,ref,color=MD,linestyle=(0,(3,2)),linewidth=.9,marker='o',markersize=2.3,markerfacecolor='white',markeredgewidth=.7,label='MD reference',zorder=2)
        ax.plot(x,pred,color=BLUE,linewidth=1.1,marker='s',markersize=2.3,label='FlexPPI',zorder=3)
        for author in [96,101]:
            j=author-95
            if valid[j]:
                ax.scatter([author],[pred[j]],s=18,facecolors='white',edgecolors=WARM,linewidths=.9,zorder=5)
        ax.set(xlim=(94.6,109.4),ylim=ylims,yticks=yticks,ylabel=ylabel)
        ax.tick_params(axis='both',labelsize=7,length=2.5,pad=2)
        ax.yaxis.label.set_size(8)
        ax.yaxis.set_label_coords(-.16,.5)
        ax.set_xticks([95,100,105,109])
        if metric=='rmsf':
            ax.tick_params(axis='x',labelbottom=False)
            for author,offset in [(96,0.03),(101,0.10)]:
                j=author-95
                ax.annotate(f'R{author}',xy=(author,pred[j]),xytext=(author,ylims[1]+offset),
                            fontsize=7,color=WARM,ha='center',va='bottom',
                            arrowprops=dict(arrowstyle='-',color=WARM,lw=.55,shrinkA=1,shrinkB=3),annotation_clip=False)
        else:
            ax.set_xlabel('Heavy-chain residue number',fontsize=7.5,labelpad=3)
        axes.append(ax)
    legend=[Line2D([0],[0],color=BLUE,marker='s',markersize=2.5,lw=1.0,label='FlexPPI'),Line2D([0],[0],color=MD,ls='--',marker='o',mfc='white',markersize=2.5,lw=.9,label='MD')]
    fig.legend(handles=legend,loc='upper center',bbox_to_anchor=(111/W,1-9.5/H),ncol=2,fontsize=7,handlelength=1.8,columnspacing=1.2,handletextpad=.5,borderpad=0)
    return axes

def contact_panel(fig):
    ax=fig.add_axes(rect(154,20,27,45))
    bars=ax.bar([0,1],occup,width=.56,color=[MD,MD],edgecolor='none',zorder=2)
    ax.set(ylim=(0,105),yticks=[0,50,100],xlim=(-.65,1.65),xticks=[0,1],xticklabels=['Main\nchain','Side\nchain'])
    ax.tick_params(axis='x',labelsize=6.5,length=0,pad=4)
    ax.tick_params(axis='y',labelsize=7,length=2.5,pad=2)
    ax.set_ylabel('Contact frames (%)',fontsize=7.5,labelpad=3)
    for bar,value in zip(bars,occup):
        ax.text(bar.get_x()+bar.get_width()/2,value+2.5,f'{value:.1f}',ha='center',va='bottom',fontsize=8,color=BLACK)
    fig.text(168/W,1-14/H,'with light chain',ha='center',fontsize=7,color=MD)
    fig.text(168/W,1-74/H,'MD · ≤4 Å',ha='center',fontsize=7,color=MD)
    return ax

def compose_figure():
    fig=plt.figure(figsize=(W/25.4,H/25.4),facecolor='white')
    heading(fig,'e','H-CDR3 environments',1)
    structure=molecular_panel(fig)
    # Export panel e before adding neighboring axes, whose y labels extend left.
    from matplotlib.transforms import Bbox
    crop_inches=Bbox.from_extents(0,0,72/25.4,H/25.4)
    for ext in ['png','pdf','svg']:
        fig.savefig(V2/f'figure4e_redraw_v2.{ext}',bbox_inches=crop_inches,pad_inches=0,dpi=600 if ext=='png' else 300)
    heading(fig,'f','H-CDR3 dynamics',74)
    heading(fig,'g','R101 contacts',148)
    profile_panel(fig);contact_panel(fig)
    # Fixed physical canvas, no post-render downscaling or automatic crop.
    with mpl.rc_context({'savefig.bbox':None}):
        for suffix in ['pdf','svg','png']:
            fig.savefig(str(OUTPUT)+'.'+suffix,dpi=600 if suffix=='png' else 300,bbox_inches=None,pad_inches=0)
    plt.close(fig)
    files=[CASE/'6A77_all_positions_predictions_and_MD.csv',CASE/'hcd3_functional_analysis_20261029/md_audit/all_h3_sidechain_backbone_and_blocks.csv',CASE/'audits/current_inference.json',Path(__file__)]
    report={'status':'rendered_pending_visual_QA','size_mm':[W,H],'PNG_dpi':600,'profiles':{'all_H3_positions':15,'valid_Hchi_positions':12,'undefined_Hchi_authors':[95,98,106],'no_downsampling':True},'contact_percent':occup.tolist(),'contact_scope':'R101 backbone/sidechain versus any light-chain heavy atom; one existing correlated 1000-frame trajectory; not independent replicates; no CI or significance test','structure':structure,'sources_sha256':{str(p):sha(p) for p in files},'checkpoint_provenance':json.loads((CASE/'audits/current_inference.json').read_text(encoding='utf-8'))['models'],'exports':[str(OUTPUT)+'.'+s for s in ['pdf','svg','png']]}
    (V2/'figure_render_provenance.json').write_text(json.dumps(report,ensure_ascii=False,indent=2),encoding='utf-8')
    for suffix in ['pdf','svg','png']:
        shutil.copy2(str(OUTPUT)+'.'+suffix,PAPER/f'figure4e_g_20261029_抗体动态预览_v2.{suffix}')
    print(json.dumps(report,ensure_ascii=False,indent=2))

if __name__=='__main__':
    compose_figure()
